def rotate_right(items, k):
    if not items:
        return []
    k %= len(items)
    cut = len(items) - k
    return items[cut:] + items[:cut]

def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for char in text:
        if char in "([{":
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack

