from collections import deque


def fewest_hops(graph, start, goal):
    if start == goal:
        return 0
    seen = {start}
    queue = deque([(start, 0)])
    while queue:
        node, distance = queue.popleft()
        for next_node in graph.get(node, []):
            if next_node == goal:
                return distance + 1
            if next_node not in seen:
                seen.add(next_node)
                queue.append((next_node, distance + 1))
    return -1

