def count_components(nodes, edges):
    links = {node: [] for node in nodes}
    for a, b in edges:
        links[a].append(b)
        links[b].append(a)
    seen = set()
    groups = 0
    for node in nodes:
        if node in seen:
            continue
        groups += 1
        seen.add(node)
        stack = [node]
        while stack:
            current = stack.pop()
            for other in links[current]:
                if other not in seen:
                    seen.add(other)
                    stack.append(other)
    return groups

