def best_path(tree):
    best = tree[0]

    def down(node):
        nonlocal best
        if node is None:
            return 0
        value, left, right = node
        from_left = max(down(left), 0)
        from_right = max(down(right), 0)
        best = max(best, value + from_left + from_right)
        return value + max(from_left, from_right)

    down(tree)
    return best

import asyncio


async def gather_limited(jobs, limit):
    if limit < 1:
        raise ValueError("limit must be at least 1")
    semaphore = asyncio.Semaphore(limit)

    async def guarded(job):
        async with semaphore:
            return await job()

    return await asyncio.gather(
        *(guarded(job) for job in jobs)
    )
